<?php
// port of the lookup routine of @photostructure/tz-lookup (CC0-1.0); data generated by build/gen-tz-data.mjs

final class TimeZoneLookup {
  private static ?array $table = null;

  // IANA zone id for the given coordinates, null for invalid coordinates
  public static function lookup(float $lat, float $lon): ?string {
    if (!(-90 <= $lat && $lat <= 90 && -180 <= $lon && $lon <= 180)) {
      return null;
    }
    if ($lat >= 90) {
      return 'Etc/GMT';
    }
    $table = self::table();
    $data = $table['data'];
    $zones = $table['zones'];
    $n = count($zones);

    $v = -1;
    $s = 48 * (180 + $lon) / 360.00000000000006;
    $u = 24 * (90 - $lat) / 180.00000000000003;
    $col = (int)$s;
    $row = (int)$u;
    $k = 96 * $row + 2 * $col;
    $k = 56 * ord($data[$k]) + ord($data[$k + 1]) - 1995;
    while ($k + $n < 3136) {
      $v = $v + $k + 1;
      $u = fmod(2 * ($u - $row), 2);
      $row = (int)$u;
      $s = fmod(2 * ($s - $col), 2);
      $col = (int)$s;
      $k = 8 * $v + 4 * $row + 2 * $col + 2304;
      $k = 56 * ord($data[$k]) + ord($data[$k + 1]) - 1995;
    }
    return $zones[$k + $n - 3136];
  }

  private static function table(): array {
    if (self::$table === null) {
      $dir = defined('APP_DATA_DIR') ? APP_DATA_DIR : __DIR__ . '/../data';
      self::$table = require $dir . '/tz-lookup.php';
    }
    return self::$table;
  }
}
